    unsigned char _body[0x338];
    CPlayerGui(CMainGameComponent* component, CWorld* world, CGamePlayerInterface* playerInterface,
               CPlayerManager* playerManager, CGraphicDataBank* bank);   // 0x0043B570
    void Open();                                            // 0x004374B0
};

